// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }

    function testFuzz_property(address sender, uint256 tokenId, bytes calldata data) public {
        vm.assume(sender != address(0));
        vm.prank(sender);
        bytes4 returned = c.onERC721Received(sender, address(0), tokenId, data);
        assertTrue(returned == bytes4(0x150b7a02));
    }
}
